import { breakpoints } from 'app/theme/foundation';

// SFCC-315 (Cart drawer): items/totals column widths for the desktop (above the desktop
// breakpoint) two-column layout, per the approved build-step spec (not independently
// re-verified against a Figma node by this commit — see this build step's own instructions) —
// no --zimm-scale equivalent at either value yet.
// audit-allow: fixed column widths from the approved build-step spec, pending a foundation token.
const ITEMS_COLUMN_WIDTH = '22.5rem'; // 360px
const TOTALS_COLUMN_WIDTH = '26.875rem'; // 430px

// gridSystem.ts names `md` "the tablet breakpoint" (768px) and `xl` "the desktop breakpoint"
// (1280px) — reusing both aliases rather than inventing a third, per this component's own
// build-step scope note.
//
// The media-query string is inlined at each use site below (matching zimmDrawer.css.ts's own
// `[`@media (min-width: ${breakpoints.md})`]:` usage) rather than hoisted to a shared const,
// purely for readability/DRY-ness at the definition site — it makes no difference to how this
// file type-checks either way (verified via `npx tsc --noEmit`). Each part below mixes plain
// mobile-default properties with media-query-keyed overrides, so TypeScript resolves any
// bracket access into this object (e.g. `body[someMediaQueryString]`) to the union of every
// property-value shape in it, not the one specific shape that's actually there at runtime —
// see zimmCartDrawer.css.test.ts's own comment on the resulting `.toEqual(...)` workaround.

export const ZimmCartDrawer = {
  parts: ['container', 'messages', 'scrollArea', 'body', 'footer'],
  baseStyle: {
    // `messages`/`scrollArea` share this real flex column so `scrollArea` below can receive its
    // remaining-space share via `flex: '1'`. `overflow: 'hidden'` here (not `auto`): once
    // `scrollArea` correctly consumes only its own fair share, this level has nothing left to
    // scroll — the two real, separate scroll layers both live one level down (see
    // `scrollArea` and `body`'s own doc comments).
    container: {
      display: 'flex',
      flexDirection: 'column',
      height: '100%',
      overflow: 'hidden',
    },
    // Reserves height even with nothing to show — designer requirement: "to prevent the cart
    // changing position depending on errors". --zimm-scale-1300 = 52px (zimmTokens.ts:168).
    // Deliberately a sibling of `scrollArea`, not inside it: this band stays put while
    // `scrollArea` scrolls beneath it.
    messages: {
      minHeight: 'var(--zimm-scale-1300)',
      paddingInline: 'var(--zimm-scale-2xl)', // 32px — mobile/tablet page gutter
      [`@media (min-width: ${breakpoints.xl})`]: {
        paddingInline: 'var(--zimm-scale-6xl)', // 128px — desktop page gutter
      },
    },
    // 1:1 Figma-alignment audit fix, 2026-09-22 (round 3 — see `body`'s own doc for rounds 1/2):
    // wraps `body` + `footer` (Zimmermann-benefits, SFCC-317) in a real scroll container of their
    // own, distinct from `body`'s own separate, independent items-column scroll. `flex: '1'`/
    // `minHeight: 0` let it receive its bounded share of `container` above; `overflowY: 'auto'`
    // is the *outer* of the two real scroll layers this drawer now has: once the items column's
    // own internal scroll (body's own `overflowY: 'auto'` Stack, in cartDrawerContainer.tsx)
    // reaches its own end, a further scroll gesture has nowhere left to go *inside* it and
    // naturally bubbles up to this layer instead — ordinary nested-scroll behaviour, not
    // hand-rolled — which is what moves `body` (items + totals together) up and reveals `footer`
    // below it. Hidden scrollbar, same reasoning/mechanism as the items column's own (Marcel's
    // direct call, 2026-09-22): scrolling itself is unaffected, only the scrollbar's own
    // rendering is suppressed.
    scrollArea: {
      flex: '1',
      minHeight: 0,
      overflowY: 'auto',
      scrollbarWidth: 'none', // Firefox
      '&::-webkit-scrollbar': { display: 'none' }, // Chromium/Safari
    },
    // Round 1 (2026-09-22): `flex: '1'`/`height: '100%'` — forced this part to always fill
    // 100% of its parent, squeezing the items column smaller to make permanent room for
    // `footer` even with one item in the cart. Wrong per Marcel's own correction: Zimmermann-
    // benefits should only take up room once a shopper actually scrolls down to it, not be
    // permanently reserved.
    // Round 2 (2026-09-22): removed the forced `height: '100%'`, kept `flex`/`minHeight: 0` —
    // fixed a *different* bug (see `container`'s round-2 history, now superseded) but hadn't
    // yet solved round 1's actual problem, since `flex: '1'` alone still force-fills.
    // Round 3 (this fix): no `flex`/`height` at all any more. `maxHeight: '100%'` (desktop step
    // only) is a cap, not a forced fill — sized against `scrollArea`'s own real, bounded height
    // (round 2's fix, still correct and still needed for *that* purpose). A short cart sizes to
    // its own natural, smaller height, leaving `footer` visible right below with no scroll
    // needed at all; a long cart hits the cap, and only then does the items column's own
    // internal `overflowY: 'auto'` (cartDrawerContainer.tsx) start doing anything — matching the
    // items column (Cart-item-group, Figma node 9323:96526) being 936px against its 857px-tall
    // parent (Cart Summary) and totals sibling (Totals-summary, both 857px) once there's enough
    // items to actually need it, not before.
    body: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      paddingInline: 'var(--zimm-scale-2xl)',
      // Tablet step restated explicitly at its own breakpoint (same values as the mobile
      // default above — fluid width, NOT a computed pixel width) — see
      // .claude/rules/overrideStyling.md's "Responsive steps are explicit media queries".
      [`@media (min-width: ${breakpoints.md})`]: {
        display: 'flex',
        flexDirection: 'column',
        width: '100%',
        paddingInline: 'var(--zimm-scale-2xl)',
      },
      // Desktop: two columns (items/totals), a 140px gap between them, a 128px page gutter each
      // side, and a height cap (see this part's own round-3 history above) so the items column
      // scrolling independently (cartDrawerContainer.tsx's own `overflowY: 'auto'` on that
      // Stack) and the totals column simply not needing to, since it fits, is what reads as
      // "sticky" next to it. `gridTemplateRows: '1fr'` makes the grid's one row fill whatever
      // height this part actually ends up at (natural or capped) so both columns stretch to it
      // (grid's default `alignItems: stretch`). `overflow: 'hidden'`: the items column's own
      // overflow is handled by its own `overflowY: 'auto'`, not by spilling past this part's box.
      //
      // Round 4 (2026-09-23, Marcel's direct decision): `minHeight: '100%'` added alongside the
      // existing `maxHeight: '100%'` — deliberately the SAME reference value, not a new one. A
      // short cart (1-2 items) used to size to its own small natural height here, leaving
      // `footer` sitting immediately below with nothing to scroll past — confirmed against the
      // real Totals-summary Figma component (node 9323:95939, file QQ427wHWEUjsjP7H8v48Rs):
      // once its own Promotion-code-container/Recommended-for-you sections are built (not yet —
      // see cartDrawerContainer.tsx's own "Column 2" doc), the totals column becomes a fixed
      // ~857px regardless of item count and naturally becomes the taller grid column for a short
      // cart, pushing `footer` past the fold on its own — this is a deliberate, temporary
      // stand-in for that not-yet-built behaviour, not a permanent design choice; revert once
      // either of those two sections ships. `minHeight`/`maxHeight` sharing one value means this
      // only ever engages when natural content is SHORTER than 100% (a short cart) — a long
      // cart's own natural content already exceeds 100%, so `maxHeight` alone still governs it,
      // completely unchanged from round 3. Grid's own default `alignItems: stretch` (this part's
      // own comment above) means the items/totals columns stretch to fill the now-taller box —
      // each renders at its own real, undistorted natural height with blank space below, not
      // squeezed or force-filled the way round 1's rejected `height: '100%'` was: that version
      // gave `footer` itself a permanent, always-visible share of this same fixed budget,
      // shrinking the items column's own available cap to make room for it. This one doesn't
      // touch `footer`'s own space or visibility at all — it only ever changes how much of
      // `body`'s own box a short cart's content fills before `footer` (unconditionally a
      // separate sibling, unconditionally reached only by scrolling) starts.
      [`@media (min-width: ${breakpoints.xl})`]: {
        display: 'grid',
        gridTemplateColumns: `${ITEMS_COLUMN_WIDTH} ${TOTALS_COLUMN_WIDTH}`,
        gridTemplateRows: '1fr',
        columnGap: 'var(--zimm-scale-3500)', // 140px
        paddingInline: 'var(--zimm-scale-6xl)', // 128px
        minHeight: '100%',
        maxHeight: '100%',
        overflow: 'hidden',
      },
    },
    // Zimmermann-benefits (SFCC-317) — see cartDrawerContainer.tsx's own doc for why this slot,
    // previously reserved for SFCC-275's button group (long since moved into `body`'s own totals
    // column instead, leaving this unused until now).
    //
    // `paddingInline` here deliberately does NOT match `messages`/`body` above: ZimmBenefits is
    // full-bleed (its own `marginInline: calc(-1 * var(--zimm-scale-2xl))` / `calc(-1 *
    // var(--zimm-scale-4xl))` at its own `BP_LARGE` breakpoint — zimmBenefits.css.ts — cancels
    // exactly 32px / 64px of parent padding, the generic ZimmDrawer/ZimmPdpDrawer gutter its own
    // comment names, NOT this drawer's own wider 128px desktop gutter). Matching that expected
    // 64px here, instead of reusing `body`'s 128px, is what makes ZimmBenefits actually bleed
    // edge-to-edge rather than sit inset by the 64px this drawer's gutter and its own
    // cancellation would otherwise disagree by.
    //
    // `marginTop` (base — same value at every breakpoint, not desktop-only): the gap between
    // Content Container's bottom edge and Zimmermann-benefits' top edge (Marcel's direct
    // report, 2026-09-22 — flush with no gap at all on tablet/mobile until this fix). Checked
    // all three real drawer frames directly, not guessed: desktop (9323:95934, Content
    // Container ends y=889, Zimmermann-benefits starts y=953), tablet (9323:65993's own nested
    // drawer-content, Cart Summary ends y=1721.2, Zimmermann-benefits starts y=1785.2), and
    // mobile (9323:66106's own nested drawer-content, Content Container ends y=1371,
    // Zimmermann-benefits starts y=1435) — all three land on the identical 64px gap, so this is
    // a real, confirmed value at every size, not the placeholder Marcel's own report allowed
    // for while this was still unchecked.
    footer: {
      paddingInline: 'var(--zimm-scale-2xl)',
      marginTop: 'var(--zimm-scale-4xl)', // 64px — Figma-confirmed at all three breakpoints
      [`@media (min-width: ${breakpoints.xl})`]: {
        paddingInline: 'var(--zimm-scale-4xl)', // 64px — matches ZimmBenefits' own cancellation
      },
    },
  },
};

import { breakpoints } from 'app/theme/foundation';

const BP_LARGE = breakpoints.xl; // 80em / 1280px — matches PDP drawer's `large` variant breakpoint
// audit-allow: 64em — no foundation breakpoint for 1024px; em is correct per overrideStyling.md Units.
const BP_DESKTOP = '64em'; // 1024px — matches Figma alias/breakpoint/desktop

export const ZimmBenefits = {
  parts: ['root'],
  baseStyle: {
    root: {
      backgroundColor: 'var(--zimm-color-ivory-200)',
      paddingTop: 'var(--zimm-scale-1600)', // 64px — Figma: alias/space/1600
      paddingBottom: 'var(--zimm-scale-1600)', // 64px — Figma: alias/space/1600
      paddingLeft: 'var(--zimm-scale-800)', // 32px — Figma: alias/space/800
      paddingRight: 'var(--zimm-scale-800)', // 32px — Figma: alias/space/800
      // Bleed edge-to-edge inside any padded drawer. Negative values cancel the drawer's
      // paddingInline: 32px on mobile+tablet (drawer mobile/tablet variant), 64px at xl+
      // (drawer large variant at ≥1280px). Verified against ZimmPdpDrawer and ZimmDrawer atom.
      marginInline: 'calc(-1 * var(--zimm-scale-2xl))',
      [`@media (min-width: ${BP_LARGE})`]: {
        marginInline: 'calc(-1 * var(--zimm-scale-4xl))',
      },
      [`@media (min-width: ${BP_DESKTOP})`]: {
        paddingLeft: 'var(--zimm-scale-6xl)', // 128px — Figma: alias/space/3200
        paddingRight: 'var(--zimm-scale-6xl)', // 128px — Figma: alias/space/3200
      },
    },
  },
};

